import SwiftUI
import SyncSpaceKit

struct MacHomeView: View { @EnvironmentObject private var state: SyncSpaceAppState; var body: some View { ScrollView { VStack(alignment: .leading, spacing: 22) { HStack { VStack(alignment: .leading) { Text("Good to see you").font(.largeTitle.bold()); Text(state.localDevice?.name ?? "Connect to the SyncSpace backend").foregroundStyle(.secondary) }; Spacer(); MacConnectionBadge(value: state.connectionState) }; HStack { card("Nearby", state.discoveredDevices.count, "antenna.radiowaves.left.and.right"); card("Trusted", state.trustedDevices.count, "checkmark.shield"); card("Active transfers", state.transferManager.active.count, "arrow.left.arrow.right") }; GroupBox("Quick actions") { HStack { Button("Discover Devices", systemImage: "arrow.clockwise") { Task { await state.refreshDiscovery() } }.buttonStyle(.borderedProminent); Button("Send Clipboard", systemImage: "doc.on.clipboard") {}.disabled(true); Button("Send File", systemImage: "paperclip") {}.disabled(true); Button("New Note", systemImage: "square.and.pencil") {}.disabled(true) }.padding(8) }; GroupBox("Recent activity") { if state.transferManager.transfers.isEmpty { ContentUnavailableView("No recent activity", systemImage: "clock") } else { ForEach(state.transferManager.transfers.prefix(4)) { transfer in HStack { Image(systemName: transfer.direction == .outbound ? "arrow.up.circle" : "arrow.down.circle"); Text(transfer.fileName); Spacer(); Text(transfer.status.rawValue).foregroundStyle(.secondary) }.padding(.vertical, 4) } } } }.padding(28) } }
    private func card(_ title: String, _ value: Int, _ icon: String) -> some View { VStack(alignment: .leading) { Image(systemName: icon).foregroundStyle(.tint); Text("\(value)").font(.largeTitle.bold()); Text(title).foregroundStyle(.secondary) }.frame(maxWidth: .infinity, alignment: .leading).padding().background(.regularMaterial, in: RoundedRectangle(cornerRadius: 14)) }
}
struct MacDevicesView: View { @EnvironmentObject private var state: SyncSpaceAppState; @State private var selected: Device.ID?; var body: some View { VStack(alignment: .leading) { Text("Devices").font(.largeTitle.bold()).padding([.top, .horizontal]); Table(state.discoveredDevices, selection: $selected) { TableColumn("Device") { device in Label(device.name, systemImage: device.deviceType == "phone" ? "iphone" : "desktopcomputer") }; TableColumn("Platform", value: \.platform); TableColumn("Address") { Text("\($0.host):\($0.port)") }; TableColumn("Trust") { Text($0.isTrusted ? "Trusted" : "Not trusted") }; TableColumn("Status") { Text($0.isOnline ? "Online" : "Offline").foregroundStyle($0.isOnline ? .green : .secondary) }; TableColumn("Last seen") { Text($0.lastSeen?.formatted(date: .abbreviated, time: .shortened) ?? "Unknown") } }.contextMenu(forSelectionType: Device.ID.self) { ids in Button("Send Clipboard") {}.disabled(ids.isEmpty); Button("Forget", role: .destructive) {}.disabled(ids.isEmpty) } primaryAction: { _ in } }.overlay { if state.discoveredDevices.isEmpty { ContentUnavailableView("No devices", systemImage: "laptopcomputer.slash", description: Text("Refresh discovery when the backend is connected.")) } } } }
